using Namaa.Application.Common.Concurrency;using Namaa.Domain.Entities;namespace Namaa.Application.JournalEntries.Dtos;public sealed record JournalEntryLineDto(long Id,long JournalEntryId,short LineNumber,long AccountId,long? BranchId,long? CostCenterId,long? ProjectId,string? Description,decimal Debit,decimal Credit,string ParentRowVersion){internal static JournalEntryLineDto FromEntity(JournalEntryLine e)=>new(e.Id,e.JournalEntryId,e.LineNumber,e.AccountId,e.BranchId,e.CostCenterId,e.ProjectId,e.Description,e.Debit,e.Credit,ConcurrencyToken.Encode(e.JournalEntry.RowVersion));}public sealed record JournalEntryDto(long Id,string EntryNumber,DateTime EntryDate,string? Description,string Status,string? SourceType,long? SourceId,long CreatedByUserId,DateTime CreatedAt,DateTime? UpdatedAt,long? PostedByUserId,DateTime? PostedAt,string RowVersion,IReadOnlyList<JournalEntryLineDto> Lines){internal static JournalEntryDto FromEntity(JournalEntry e)=>new(e.Id,e.EntryNumber,e.EntryDate,e.Description,e.Status,e.SourceType,e.SourceId,e.CreatedByUserId,e.CreatedAt,e.UpdatedAt,e.PostedByUserId,e.PostedAt,ConcurrencyToken.Encode(e.RowVersion),e.Lines.Select(JournalEntryLineDto.FromEntity).ToList());}
